const directions: Direction[] = ['up', 'left', 'right', 'down'];
export const lotteCards: SwipeCard[] = rows.map(([topic, question, choices, explanation, sourceNote], index) => {
  const correct = directions[index % 4];
  const wrong = choices.slice(1);
  const answers = Object.fromEntries(directions.map(d => [d, d === correct ? choices[0] : wrong.shift()!])) as Record<Direction, string>;
  return { id: `lotte-giants-${String(index + 1).padStart(3, '0')}`, topic, question, answers, correct, explanation, sourceNote };
});

/** 찐팬 난이도 카드(단원 이름이 '찐팬'으로 시작). */
export const isHardcore = (card: SwipeCard) => card.topic.startsWith('찐팬');
